import { FileSystem, type File, path as pathModule, GUID } from '@servicenow/sdk-build-core'
import * as os from 'os'

export function writeFileWithParentDirs(fs: FileSystem, { path, content }: File): void {
    const parentDirectory = pathModule.dirname(path)
    if (!FileSystem.existsSync(fs, parentDirectory)) {
        fs.mkdirSync(parentDirectory, { recursive: true })
    }

    fs.writeFileSync(path, content, { encoding: 'utf-8' })
}

export function createDirIfNotExists(dirPath: string, fs: FileSystem) {
    if (!FileSystem.existsSync(fs, dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true })
    }
}

export function defaultDownloadDir() {
    //Generate a unique temporary path for unpacking to avoid collisions
    return pathModule.join(os.tmpdir(), '.now/metadata', GUID())
}

export function writeFileStream(fs: FileSystem, filePath: string, content: ReadableStream<Uint8Array>) {
    const fileStream = FileSystem.createWriteStream(fs, filePath)
    // `createWriteStream` returns a Node-like Writable,
    // but we need a browser-like WritableStream 🙃
    return content.pipeTo(
        new WritableStream({
            write: (chunk) => {
                return new Promise((resolve, reject) => {
                    fileStream.write(chunk, (error) => {
                        if (error) {
                            reject(error)
                        } else {
                            resolve()
                        }
                    })
                })
            },
            close: () => {
                return new Promise((resolve, reject) => {
                    fileStream.end((error: Error) => {
                        if (error) {
                            reject(error)
                        } else {
                            resolve()
                        }
                    })
                })
            },
            abort: (reason) => {
                return new Promise((_, reject) => {
                    fileStream.end((error: Error) => {
                        reject(reason ?? error)
                    })
                })
            },
        })
    )
}
